-- REVIEW ONLY: requires explicit approval for renewed private-data access.
-- Same reader and credential; expiry extended to November 5, 2026, 15:30 India.
-- Seven SELECT-only grants; no default grants, table writes or Auth secrets.
-- One new PUBLIC definer EXECUTE path narrowed while app callers/triggers remain.
BEGIN;
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
DO $guard$ BEGIN
 IF '__APPROVE_READER_RENEWAL_20261029__' = '__APPROVE_' || 'READER_RENEWAL_20261029__' THEN RAISE EXCEPTION 'Review-only renewal requires approval'; END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='d1_migration_reader_20261022' AND rolcanlogin AND rolbypassrls AND NOT rolsuper AND NOT rolcreaterole AND NOT rolcreatedb AND NOT rolreplication AND NOT rolinherit AND rolconnlimit=3 AND rolvaliduntil='2026-10-29 10:00:00+00'::timestamptz) THEN RAISE EXCEPTION 'Existing reader configuration changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_auth_members WHERE member=(SELECT oid FROM pg_roles WHERE rolname='d1_migration_reader_20261022')) THEN RAISE EXCEPTION 'Unexpected reader memberships'; END IF;
 IF (SELECT array_agg(tablename::text ORDER BY tablename) FROM pg_tables WHERE schemaname='public') IS DISTINCT FROM ARRAY['audit_logs','award_history','badge_hits','badge_rewards','bid_results','blocked_domains','buyer_claims','buyer_domains','buyer_follows','buyer_pages','buyer_permissions','buyer_source_requests','case_studies','case_study_share_links','contact_requests','contractor_activity','correction_requests','device_push_tokens','digest_subscribers','duplicate_reviews','email_consents','email_suppressions','forum_categories','forum_category_mods','forum_category_redirects','forum_mod_log','forum_poll_options','forum_poll_votes','forum_polls','forum_post_votes','forum_posts','forum_profiles','forum_reply_notifications','forum_reports','forum_reputation_events','forum_room_follows','forum_thread_ratings','forum_threads','insight_brief_log','insight_rejections','intel_access','job_applications','job_posts','karma_events','landing_counts','lead_alert_log','lifecycle_sends','major_projects','marketplace_listings','marketplace_messages','notification_preferences','notifications','onboarding_steps','open_data_runs','org_karma','org_link_clicks','organization_categories','organization_join_requests','organization_members','organization_property_types','organization_regions','organization_risk','organizations','permit_leads','planned_procurements','platform_settings','profile_views','property_types','rate_limit_hits','region_requests','regional_waitlist','regions','resources','review_invites','rfp_bid_checks','rfp_categories','rfp_changes','rfp_documents','rfp_interests','rfp_posts','rfp_views','saved_rfps','signup_attribution','site_events','site_page_views','site_referrers','site_visitors','sponsor_clicks','sponsor_impressions','sponsors','stripe_webhook_events','subscriptions','talent_contacts','talent_endorsements','talent_private','talent_profiles','town_invites','town_job_addenda','town_job_log','town_job_questions','town_job_results','trade_categories','trade_trials','trusted_list_items','trusted_lists','users_profile','vendor_reviews','winner_claims']::text[] THEN RAISE EXCEPTION 'Live table inventory changed'; END IF;
 IF md5(pg_get_functiondef('public.guard_organization_link_fields()'::regprocedure)) <> '794eb49b961c38d9791a813dc6d399e8' OR md5(pg_get_functiondef('public.has_active_trade_access(uuid)'::regprocedure)) <> '493b2cd89346e24c089838165eaef7d0' OR md5(pg_get_functiondef('public.has_intel_access(uuid)'::regprocedure)) <> '9ff939f9100552ac1261d49e2c2b7ac5' OR md5(pg_get_functiondef('public.is_admin(uuid)'::regprocedure)) <> '41bc6018cf2cb834cf0502373e3a9240' OR md5(pg_get_functiondef('public.is_org_member(uuid, uuid)'::regprocedure)) <> 'ca8cec8b9e56926ca7bd47c82afca213' THEN RAISE EXCEPTION 'Audited helper definitions changed'; END IF;
 IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND has_table_privilege('d1_migration_reader_20261022',format('%I.%I',schemaname,tablename),'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER')) THEN RAISE EXCEPTION 'Reader has table write privileges'; END IF;
 IF EXISTS(SELECT 1 FROM pg_namespace n WHERE n.nspname NOT IN ('pg_catalog','information_schema') AND has_schema_privilege('d1_migration_reader_20261022',n.oid,'CREATE')) THEN RAISE EXCEPTION 'Reader can create persistent schema objects'; END IF;
 IF (SELECT array_agg(format('%I.%I(%s)',n.nspname,p.proname,oidvectortypes(p.proargtypes)) ORDER BY format('%I.%I(%s)',n.nspname,p.proname,oidvectortypes(p.proargtypes)) COLLATE "C") FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE (n.nspname IN ('public','auth') OR has_schema_privilege('d1_migration_reader_20261022',n.oid,'USAGE')) AND p.prosecdef AND EXISTS(SELECT 1 FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE a.grantee=0 AND a.privilege_type='EXECUTE')) IS DISTINCT FROM ARRAY['public.guard_organization_link_fields()','public.has_active_trade_access(uuid)','public.has_intel_access(uuid)','public.is_admin(uuid)','public.is_org_member(uuid, uuid)']::text[] THEN RAISE EXCEPTION 'Inherited definer inventory changed'; END IF;
 IF has_column_privilege('d1_migration_reader_20261022','auth.users'::regclass,'encrypted_password','SELECT') THEN RAISE EXCEPTION 'Reader can read Auth secrets'; END IF;
END $guard$;
REVOKE EXECUTE ON FUNCTION public.guard_organization_link_fields() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.guard_organization_link_fields() TO anon,authenticated,service_role;
GRANT SELECT ON public."blocked_domains",public."contractor_activity",public."open_data_runs",public."org_link_clicks",public."organization_risk",public."permit_leads",public."planned_procurements" TO "d1_migration_reader_20261022";
ALTER ROLE "d1_migration_reader_20261022" VALID UNTIL '2026-11-05 10:00:00+00';
DO $verify$ BEGIN
 IF EXISTS(SELECT 1 FROM pg_tables WHERE schemaname='public' AND (NOT has_table_privilege('d1_migration_reader_20261022',format('%I.%I',schemaname,tablename),'SELECT') OR has_table_privilege('d1_migration_reader_20261022',format('%I.%I',schemaname,tablename),'INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER'))) THEN RAISE EXCEPTION 'Read-only renewal validation failed'; END IF;
 IF NOT has_table_privilege('d1_migration_reader_20261022','public.d1_migration_auth_ids_20261022','SELECT') OR has_column_privilege('d1_migration_reader_20261022','auth.users'::regclass,'encrypted_password','SELECT') OR has_function_privilege('d1_migration_reader_20261022','public.guard_organization_link_fields()','EXECUTE') THEN RAISE EXCEPTION 'Reader boundary validation failed'; END IF;
END $verify$;
COMMIT;
